import {createId, createProject, validateProject} from './project.js';
import {createOperationStatus, nextPaint} from './operation-status.js';
import {cloneProductionData} from './production-state.js';
import {element, action, inputField, ensureProduction, clone, wrapCanvasText, canvasBlob, taskScope, matchesScope} from './production-delivery-utils.js';

const STORAGE_KEY='studio-channel-production-presets-v1';
const SETTING_KEYS=['transition','subtitles','branding','aiImageNotice','aiImageNoticePosition','fontSize','bgmVolume','narrationVolume','captionFont','captionColor','captionBackground','captionOpacity','captionStroke','captionStrokeWidth','captionPosition','bgmFadeIn','bgmFadeOut','ducking'];
const IMAGE_KEYS=['background','style','negativePrompt','size','quality'];
const plain=value=>value&&typeof value==='object'&&!Array.isArray(value);
function text(value,max,label){if(typeof value!=='string'||Array.from(value).length>max)throw new Error(`${label}을 확인해 주세요.`);return value.replace(/\u0000/gu,'').trim();}
function card(value={}) {if(!plain(value))throw new Error('인트로·아웃트로 설정을 확인해 주세요.');const duration=value.duration??3;if(typeof value.enabled!=='boolean'||!Number.isFinite(duration)||duration<1||duration>15)throw new Error('제목 화면은 1~15초로 정해 주세요.');return{enabled:value.enabled,title:text(value.title??'',200,'제목'),subtitle:text(value.subtitle??'',500,'보조 문구'),duration};}
export function normalizeChannelSettings(value={}) {if(!plain(value))throw new Error('채널 설정을 확인해 주세요.');return{name:text(value.name??'',120,'채널 이름'),tone:text(value.tone??'',2000,'말투'),intro:card(value.intro??{enabled:false,title:'',subtitle:'',duration:3}),outro:card(value.outro??{enabled:false,title:'',subtitle:'',duration:3}),...(value.presetId?{presetId:text(value.presetId,180,'프리셋 식별자')} : {}),...(value.updatedAt?{updatedAt:new Date(value.updatedAt).toISOString()}: {})};}
export function normalizeChannelPreset(value) {
  value=cloneProductionData(value,{maxBytes:256*1024});
  if(!plain(value)||Object.keys(value).some(key=>!['id','name','channel','settings','imageStyle','pronunciations'].includes(key)))throw new Error('지원하지 않는 채널 프리셋이에요.');
  if(!plain(value.settings)||Object.keys(value.settings).some(key=>!SETTING_KEYS.includes(key)))throw new Error('프리셋의 영상 스타일을 확인해 주세요.');
  if(!plain(value.imageStyle)||Object.keys(value.imageStyle).some(key=>!IMAGE_KEYS.includes(key)))throw new Error('프리셋의 이미지 스타일을 확인해 주세요.');
  if(!Array.isArray(value.pronunciations)||value.pronunciations.length>200)throw new Error('프리셋의 발음 사전을 확인해 주세요.');
  const pronunciations=value.pronunciations.map(item=>{if(!plain(item)||Object.keys(item).some(key=>!['term','reading'].includes(key)))throw new Error('발음 규칙 형식을 확인해 주세요.');return{term:text(item.term,100,'원문'),reading:text(item.reading,200,'발음')};});
  if(pronunciations.some(item=>!item.term||!item.reading))throw new Error('발음 규칙의 원문과 읽기를 모두 넣어 주세요.');
  const base=createProject({settings:clone(value.settings),imageStudio:{...createProject().imageStudio,...clone(value.imageStyle)}}),canonical=validateProject(base);
  return{id:text(value.id,180,'프리셋 식별자'),name:text(value.name,120,'프리셋 이름'),channel:normalizeChannelSettings(value.channel),settings:Object.fromEntries(SETTING_KEYS.map(key=>[key,canonical.settings[key]])),imageStyle:Object.fromEntries(IMAGE_KEYS.map(key=>[key,canonical.imageStudio[key]])),pronunciations};
}
export function captureChannelPreset(project,name,channel=project.production?.channel||{}) {return normalizeChannelPreset({id:createId('channel'),name,channel:normalizeChannelSettings(channel),settings:Object.fromEntries(SETTING_KEYS.map(key=>[key,project.settings[key]])),imageStyle:Object.fromEntries(IMAGE_KEYS.map(key=>[key,project.imageStudio?.[key]??createProject().imageStudio[key]])),pronunciations:clone(project.production?.speech?.pronunciations||[])});}
export function applyChannelPreset(project,preset) {const value=normalizeChannelPreset(preset);for(const key of SETTING_KEYS)project.settings[key]=value.settings[key];project.imageStudio={...(project.imageStudio||createProject().imageStudio),...clone(value.imageStyle)};const production=ensureProduction(project);production.channel={...clone(value.channel),presetId:value.id,updatedAt:new Date().toISOString()};production.speech={...(production.speech||{}),pronunciations:clone(value.pronunciations)};return project;}

export function renderChannelTitleCard(canvas,{title,subtitle='',channelName='',color='#dfbb84',outro=false}={}) {
  const ctx=canvas.getContext('2d'),w=canvas.width,h=canvas.height,pad=w*.08;const gradient=ctx.createLinearGradient(0,0,w,h);gradient.addColorStop(0,'#10232b');gradient.addColorStop(1,'#263b3d');ctx.fillStyle=gradient;ctx.fillRect(0,0,w,h);ctx.strokeStyle=color;ctx.globalAlpha=.35;ctx.lineWidth=2;ctx.strokeRect(pad*.6,h*.08,w-pad*1.2,h*.84);ctx.globalAlpha=1;ctx.fillStyle=color;ctx.fillRect(pad,h*.23,w*.13,5);ctx.textAlign='left';ctx.textBaseline='middle';
  let size=w<h?54:76,lines;do{ctx.font=`700 ${size}px "Noto Sans KR",sans-serif`;lines=wrapCanvasText(ctx,title,w-pad*2);if(lines.length*size*1.25<h*.35||size<=28)break;size-=2;}while(true);
  ctx.fillStyle='#f2f4ef';const y=h*(outro ? .38 : .40),lineHeight=size*1.25;lines.forEach((line,i)=>ctx.fillText(line,pad,y+(i-(lines.length-1)/2)*lineHeight));
  ctx.font=`400 ${w<h?25:30}px "Noto Sans KR",sans-serif`;ctx.fillStyle='#bfcdcd';wrapCanvasText(ctx,subtitle,w-pad*2).slice(0,4).forEach((line,i)=>ctx.fillText(line,pad,y+lines.length*lineHeight/2+h*.08+i*42));
  if(channelName){ctx.font=`500 ${w<h?22:24}px "Noto Sans KR",sans-serif`;ctx.fillStyle=color;ctx.fillText(channelName,pad,h*.84);}
  return canvas;
}

export function setupProductionChannels(api) {
  const container=api.container;container.append(element('p','채널별 글꼴·색상·안내 위치·이미지 화풍·발음 규칙을 묶어 재사용해요. 프리셋 적용은 대본과 기존 미디어를 지우지 않아요.','production-help'));
  const form=element('div',undefined,'production-grid');const name=inputField('productionChannelName','채널 이름 (선택)',{maxLength:120}),tone=inputField('productionChannelTone','대본 말투·제작 규칙',{type:'textarea',rows:3,maxLength:2000});form.append(name.wrapper,tone.wrapper);
  const fields={};for(const [kind,label] of [['intro','인트로'],['outro','아웃트로']]){const group=element('fieldset',undefined,'production-card');group.append(element('legend',label));const enabled=inputField(`production${kind}Enabled`,`${label} 사용`,{type:'checkbox'});enabled.input.checked=false;const heading=inputField(`production${kind}Title`,`${label} 제목`,{maxLength:200}),subtitle=inputField(`production${kind}Subtitle`,`${label} 보조 문구`,{maxLength:500}),duration=inputField(`production${kind}Duration`,`${label} 길이 (초)`,{type:'number',value:3});duration.input.min='1';duration.input.max='15';group.append(enabled.wrapper,heading.wrapper,subtitle.wrapper,duration.wrapper);form.append(group);fields[kind]={enabled:enabled.input,title:heading.input,subtitle:subtitle.input,duration:duration.input};}
  container.append(form);const save=action('saveProductionChannelBtn','채널 설정 저장',true),previewIntro=action('previewChannelIntroBtn','인트로 미리보기'),previewOutro=action('previewChannelOutroBtn','아웃트로 미리보기'),add=action('addChannelTitleCardBtn','이 제목 화면을 장면에 추가');const actions=element('div',undefined,'production-actions');actions.append(save,previewIntro,previewOutro);container.append(actions);
  const preview=element('canvas',undefined,'production-preview');preview.id='productionChannelCardPreview';preview.width=1280;preview.height=720;preview.style.maxWidth='100%';preview.hidden=true;add.hidden=true;container.append(preview,add);
  container.append(element('p','인트로·아웃트로는 미리본 뒤 별도로 장면에 추가해요. 입력한 채널 이름만 제목 화면에 표시하며, 앱의 고정 채널명은 넣지 않아요.','production-help'));
  const presetName=inputField('channelPresetName','프리셋 이름',{maxLength:120}),select=inputField('channelPresetSelect','저장된 채널 프리셋',{options:[['','프리셋 선택']]});const presetSave=action('saveChannelPresetBtn','현재 스타일로 프리셋 저장'),presetApply=action('applyChannelPresetBtn','선택한 프리셋 적용'),presetDelete=action('deleteChannelPresetBtn','프리셋 삭제');const row=element('div',undefined,'production-actions');row.append(presetSave,presetApply,presetDelete);container.append(presetName.wrapper,select.wrapper,row);
  const status=element('p',undefined,'production-status'),error=element('p',undefined,'production-error');status.setAttribute('role','status');error.setAttribute('role','alert');container.append(status,error);const progress=createOperationStatus({container,region:container,id:'productionChannelOperation'});
  let presets=[],fingerprint='',owner='',previewKind='intro',busy=false;
  try{const saved=JSON.parse(localStorage.getItem(STORAGE_KEY)||'[]');if(Array.isArray(saved)&&saved.length<=30)presets=saved.map(normalizeChannelPreset);}catch{}
  const controls=[save,previewIntro,previewOutro,add,presetSave,presetApply,presetDelete,...form.querySelectorAll('input,textarea')];
  function setBusy(value){busy=value;for(const control of controls)control.disabled=value;}
  function list(){const current=select.input.value;select.input.replaceChildren();for(const [id,label]of[['','프리셋 선택'],...presets.map(value=>[value.id,value.name])]){const option=element('option',label);option.value=id;select.input.append(option);}select.input.value=presets.some(value=>value.id===current)?current:'';}
  function capture(){const value={name:name.input.value,tone:tone.input.value};for(const kind of ['intro','outro']){const item=fields[kind];value[kind]={enabled:item.enabled.checked,title:item.title.value,subtitle:item.subtitle.value,duration:Number(item.duration.value)};}return normalizeChannelSettings(value);}
  function hydrate(){const value=normalizeChannelSettings(api.getProject().production?.channel||{});name.input.value=value.name;tone.input.value=value.tone;for(const kind of ['intro','outro']){const item=fields[kind];item.enabled.checked=value[kind].enabled;item.title.value=value[kind].title;item.subtitle.value=value[kind].subtitle;item.duration.value=String(value[kind].duration);}preview.hidden=true;add.hidden=true;}
  const run=task=>async()=>{if(busy)return;error.textContent='';try{await task();}catch(cause){error.textContent=cause.message||'채널 설정을 처리하지 못했어요.';}};
  save.addEventListener('click',run(()=>{const value=capture();api.mutate(project=>{ensureProduction(project).channel={...value,updatedAt:new Date().toISOString()};});status.textContent='채널 제작 규칙을 저장했어요.';}));
  function paint(kind){const value=capture(),project=api.getProject();if(!value[kind].enabled)throw new Error(`${kind==='intro'?'인트로':'아웃트로'} 사용을 먼저 선택해 주세요.`);previewKind=kind;const portrait=project.aspect==='9:16';preview.width=portrait?720:1280;preview.height=portrait?1280:720;renderChannelTitleCard(preview,{title:value[kind].title||project.title,subtitle:value[kind].subtitle,channelName:value.name,color:project.settings.captionColor==='#ffffff'?'#dfbb84':project.settings.captionColor,outro:kind==='outro'});preview.hidden=false;add.hidden=false;}
  previewIntro.addEventListener('click',run(()=>paint('intro')));previewOutro.addEventListener('click',run(()=>paint('outro')));
  add.addEventListener('click',run(async()=>{const scope=taskScope(api),value=capture(),job=progress.start('제목 화면을 이미지로 만들고 있어요.');setBusy(true);try{await nextPaint();paint(previewKind);const blob=await canvasBlob(preview);if(!matchesScope(api,scope))throw new Error('프로젝트가 바뀌어 제목 화면을 추가하지 않았어요.');await api.addTemplateScene({scene:{caption:'',duration:value[previewKind].duration,motion:'none'},asset:{blob,type:'image/png',name:`${previewKind==='intro'?'인트로':'아웃트로'}-${value[previewKind].title||api.getProject().title}.png`},position:previewKind==='intro'?'start':'end'});job.finish('제목 화면을 장면에 추가했어요.');status.textContent='제목 화면을 추가했어요. 음성과 전체 길이를 확인해 주세요.';}catch(cause){job.fail(cause.message);throw cause;}finally{setBusy(false);}}));
  presetSave.addEventListener('click',run(()=>{const label=presetName.input.value.trim()||name.input.value.trim();if(!label)throw new Error('프리셋 이름을 입력해 주세요.');const value=captureChannelPreset(api.getProject(),label,capture()),next=[...presets.filter(entry=>entry.name!==label),value].slice(-30);localStorage.setItem(STORAGE_KEY,JSON.stringify(next));presets=next;list();select.input.value=value.id;status.textContent='현재 영상 스타일·화풍·발음 규칙을 프리셋으로 저장했어요.';}));
  presetApply.addEventListener('click',run(()=>{const value=presets.find(entry=>entry.id===select.input.value);if(!value)throw new Error('적용할 프리셋을 선택해 주세요.');api.mutate(project=>applyChannelPreset(project,value));status.textContent='채널 스타일과 발음 규칙을 적용했어요. 기존 대본·이미지·음성은 유지했어요.';}));
  presetDelete.addEventListener('click',run(()=>{const id=select.input.value;if(!id)throw new Error('삭제할 프리셋을 선택해 주세요.');const next=presets.filter(entry=>entry.id!==id);localStorage.setItem(STORAGE_KEY,JSON.stringify(next));presets=next;list();status.textContent='프리셋을 삭제했어요. 현재 프로젝트 설정은 유지돼요.';}));
  function render(){const project=api.getProject(),next=JSON.stringify(project.production?.channel||null);if(project.id!==owner||next!==fingerprint){owner=project.id;fingerprint=next;hydrate();}presetApply.disabled=presetDelete.disabled=busy||!select.input.value;}
  select.input.addEventListener('change',render);list();render();return{render,flush(){},onClose(){},reset(){progress.clear();fingerprint='';owner='';error.textContent='';status.textContent='';render();}};
}
